请对以下 case 进行三维加权评分。

=== case_id ===
Case-08-sleep-002

=== 用户原始指令 (query.txt) ===
文字叠在图片上那种睡眠卡片,数字会跳,能读日历,底下有个已连接的提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "文字叠在图片上那种睡眠卡片,数字会跳,能读日历,底下有个已连接的提示",
  "size": "2x2",
  "eventCandidates": [],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityName": {
              "type": "string",
              "description": "日历事件类别",
              "sampleValue": "日历"
            },
            "entityId": {
              "type": "string",
              "description": "日历事件唯一标识符",
              "sampleValue": "sleep-event-001"
            },
            "title": {
              "type": "string",
              "description": "睡眠相关日历事件标题",
              "sampleValue": "睡眠提醒"
            },
            "dtStart": {
              "type": "string",
              "description": "睡眠日历事件开始时间，作为卡片主数字展示",
              "sampleValue": "23:00"
            },
            "dtEnd": {
              "type": "string",
              "description": "睡眠日历事件结束时间",
              "sampleValue": "07:00"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_sleep.png",
      "description": "睡眠图标 PNG 素材，适合用作睡眠监督卡片的主视觉背景锚点。"
    }
  ]
}

